import{_ as o}from"./chunks/image1.iISxgozC.js";import{_ as r,C as n,o as s,c as i,am as t,E as l}from"./chunks/framework.CenUaW7a.js";const c="/projects/AiMechaM1/en/advanced-kit/assets/image1.DUCTp15b.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image5.CTCOcieq.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image6.DSz899A_.png",p="/projects/AiMechaM1/en/advanced-kit/assets/45.Df73M8fO.png",m="/projects/AiMechaM1/en/advanced-kit/assets/46.CjRqRBIj.png",g="/projects/AiMechaM1/en/advanced-kit/assets/47.G40m7kA4.png",u="/projects/AiMechaM1/en/advanced-kit/assets/48.BU_dqmNw.png",w="/projects/AiMechaM1/en/advanced-kit/assets/49.UXR71Q5Y.png",f="/projects/AiMechaM1/en/advanced-kit/assets/50.CFH0EraN.png",y="/projects/AiMechaM1/en/advanced-kit/assets/51.B_qYfn0X.png",_="/projects/AiMechaM1/en/advanced-kit/assets/52.IJUqfg97.png",C=JSON.parse('{"title":"3.1 Lesson 1: Basic Hardware Structure","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.1 Lesson 1 Basic Hardware Structure.md","filePath":"docs/3. Course materials/3.1 Lesson 1 Basic Hardware Structure.md"}'),b={name:"docs/3. Course materials/3.1 Lesson 1 Basic Hardware Structure.md"};function v(M,e,A,x,k,q){const a=n("Pdf");return s(),i("div",null,[e[0]||(e[0]=t('<h1 id="_3-1-lesson-1-basic-hardware-structure" tabindex="-1">3.1 Lesson 1: Basic Hardware Structure <a class="header-anchor" href="#_3-1-lesson-1-basic-hardware-structure" aria-label="Permalink to &quot;3.1 Lesson 1: Basic Hardware Structure&quot;">​</a></h1><h2 id="_3-1-1-lesson-introduction" tabindex="-1">3.1.1 Lesson Introduction <a class="header-anchor" href="#_3-1-1-lesson-introduction" aria-label="Permalink to &quot;3.1.1 Lesson Introduction&quot;">​</a></h2><p>Starting with hardware assembly, this lesson systematically introduces the overall architecture and core components of the AiMecha M1 Mecanum-wheel car. It focuses on two core concepts: &quot;the dual-controller drive architecture&quot; and &quot;the motion principles of Mecanum wheels&quot;. The lesson examines key components including the controller, chassis controller, encoder motors, and line-following sensors. Through force analysis, it explains how Mecanum wheels achieve omnidirectional movement and derives 9 trajectories across 18 motion directions, building a solid hardware foundation for subsequent programming projects.</p><img loading="lazy" height="2000" width="2000" src="'+o+'" class="common_img" style="width:400px;aspect-ratio:2000 / 2000;"><h2 id="_3-1-2-learning-objectives" tabindex="-1">3.1.2 Learning Objectives <a class="header-anchor" href="#_3-1-2-learning-objectives" aria-label="Permalink to &quot;3.1.2 Learning Objectives&quot;">​</a></h2><ol><li><p>Understand the overall hardware architecture of the AiMecha M1 Mecanum-wheel car and how the dual controllers collaborate. Learn the structural composition of Mecanum wheels and the design principle behind their 45° rollers.</p></li><li><p>Complete the hardware assembly of the Mecanum-wheel car independently and distinguish the mounting positions of A-wheels and B-wheels. Identify the functions and port labels on the controller.</p></li><li><p>Develop a systems-thinking approach to hierarchical control by separating upper-level decision-making from lower-level execution. Build physical modeling skills by deducing motion outcomes through force analysis.</p></li><li><p>Explore real-world applications of omnidirectional movement in warehouse AGVs and industrial transport robots. Understand the technical advantages and ideal use cases of Mecanum wheels compared to standard wheels.</p></li></ol><h2 id="_3-1-3-preparation" tabindex="-1">3.1.3 Preparation <a class="header-anchor" href="#_3-1-3-preparation" aria-label="Permalink to &quot;3.1.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation:</strong></p><ul><li>AiMecha M1 Mecanum-Wheel Car Standard Kit</li></ul><h2 id="_3-1-4-hands-on-project" tabindex="-1">3.1.4 Hands-On Project <a class="header-anchor" href="#_3-1-4-hands-on-project" aria-label="Permalink to &quot;3.1.4 Hands-On Project&quot;">​</a></h2><p><strong>(1) Project Analysis</strong></p><p>AiMecha M1 adopts a dual-controller hierarchical architecture. Serving as the &quot;brain&quot; of the car, the upper-level controller runs programs, collects sensor data, and issues motion commands. Meanwhile, the lower-level chassis controller acts as the &quot;driver&quot;, receiving commands to precisely regulate the four encoder motors. The two controllers communicate via a serial port. The controller simply issues commands, while the chassis controller handles wheel speed calculations and motor driving. The ultrasonic sensor and 6-channel line follower sensors connect directly to the controller for centralized data processing and decision-making. The system uses an isolated power supply, equipping the chassis and the controller with separate batteries and charging ports to prevent high-power motor operation from interfering with the controller.</p><img loading="lazy" height="1312" width="3360" src="'+c+'" class="common_img" style="width:600px;aspect-ratio:3360 / 1312;"><p><strong>(2) Core Hardware Modules</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">Module Category</th><th style="text-align:left;">Core Module</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:left;">Controller</td><td style="text-align:left;">Mecha controller</td><td style="text-align:left;">Acts as the brain of the car to execute programs, process sensor data, and issue motion commands.</td></tr><tr><td style="text-align:left;">Motion control</td><td style="text-align:left;">Chassis controller</td><td style="text-align:left;">Acts as the driver of the car to receive commands and precisely control the four encoder motors driving the Mecanum wheels.</td></tr><tr><td style="text-align:left;">Drive mechanism</td><td style="text-align:left;">Mecanum wheels: A-wheels and B-wheels</td><td style="text-align:left;">Features a hub with 45° angled rollers to achieve omnidirectional movement through wheel speed combinations.</td></tr></tbody></table><p><strong>(3) Hardware Assembly</strong></p><p>💡 M1 Assembly Steps:</p>',17)),l(a,{src:"../../_static/shared/pdf/AiMecha M1 English accessory assembly step diagram.pdf"}),e[1]||(e[1]=t('<p><strong>(4) Controller Port Identification and Functions</strong></p><ul><li><p>Identify the 8 sensor ports A through H, and understand the 4-pin wiring standard.</p></li><li><p>Identify the locations and functions of the encoder motor ports and bus servo ports S1 and S2.</p></li><li><p>Locate the power switch, charging port, program upload port, and power indicator.</p></li><li><p>Locate the programmable buttons, RGB LEDs, and buzzer, and understand their feedback functions.</p></li></ul><img loading="lazy" height="1248" width="3552" src="'+h+'" class="common_img" style="width:600px;aspect-ratio:3552 / 1248;"><img loading="lazy" height="4080" width="4000" src="'+d+'" class="common_img" style="width:400px;aspect-ratio:4000 / 4080;"><p><strong>(5) Mecanum Wheel Structure</strong></p><p>The defining feature of a Mecanum wheel is the ring of small, freely rotating rollers mounted around the circumference of the hub. These rollers are arranged at a specific angle, much like precision bevel gears. This structure allows the wheel not only to roll forward and backward, but also to move laterally and diagonally.</p><img loading="lazy" height="231" width="615" src="'+p+'" class="common_img" style="width:400px;aspect-ratio:615 / 231;"><p>A Mecanum wheel consists of a central hub and multiple angled rollers. The hub serves as the main mounting frame, while the drum-shaped rollers are mounted around its perimeter. The rotational axis of each roller is set at a 45° angle to the main wheel axle. Mecanum wheels operate in sets of four, comprising two left-handed wheels, known as A-wheels, and two right-handed wheels, known as B-wheels. The A-wheels and B-wheels are mirror images of each other.</p><img loading="lazy" height="388" width="495" src="'+m+'" class="common_img" style="width:400px;aspect-ratio:495 / 388;"><p><strong>(6) Motion Principles</strong></p><img loading="lazy" height="300" width="854" src="'+g+'" class="common_img" style="width:400px;aspect-ratio:854 / 300;"><p>Force analysis focuses on the bottom roller in direct contact with the ground, whose orientation runs crosswise to the roller at the top of the wheel. Consider the forward rotation of the wheel, analyzing only the roller in contact with the ground. As the wheel rotates forward, the contacting roller acts as an instantaneous stationary point, upon which the ground exerts a forward static frictional force. This frictional force can be decomposed into two components: one along the roller axis and the other perpendicular to it.</p><p><strong>1. Force Analysis of Forward and Backward Movement</strong></p><p>When all four Mecanum wheels rotate at the same speed in the same direction, the lateral force components cancel out. High-speed forward rotation drives the car straight ahead, while high-speed reverse rotation drives it straight back.</p><img loading="lazy" height="1696" width="2560" src="'+u+'" class="common_img" style="width:400px;aspect-ratio:2560 / 1696;"><p><strong>2. Force Analysis of Left and Right Steering</strong></p><p>&quot;Differential steering&quot; creates a speed difference between the left and right wheels of the car. When turning left, the right wheels rotate faster than the left wheels. When turning right, the left wheels rotate faster than the right wheels.</p><img loading="lazy" height="377" width="567" src="'+w+'" class="common_img" style="width:400px;aspect-ratio:567 / 377;"><p><strong>3. Force Analysis of In-Place Rotation</strong></p><p>When the left and right Mecanum wheels rotate in opposite directions, they generate a rotational torque. Precisely controlling the magnitude and direction of the wheel speeds produces stable in-place rotation. For clockwise rotation, the left wheels rotate forward while the right wheels rotate backward. Counterclockwise rotation reverses these directions.</p><img loading="lazy" height="377" width="567" src="'+f+'" class="common_img" style="width:400px;aspect-ratio:567 / 377;"><p><strong>4. Left and Right Lateral Movement</strong></p><p>When the two diagonally opposite A-type Mecanum wheels rotate in the same direction, and the two diagonally opposite B-type Mecanum wheels rotate together in the opposite direction, the longitudinal force components cancel each other out while the lateral force components combine. As a result, the chassis maintains its orientation, achieving agile left-to-right lateral movement.</p><img loading="lazy" height="1696" width="2560" src="'+y+'" class="common_img" style="width:400px;aspect-ratio:2560 / 1696;"><p><strong>5. Force Analysis of Diagonal Movement</strong></p><p>Based on Mecanum wheel mechanics, when the A-wheels remain stationary and the B-wheels rotate forward, the car moves diagonally front-left. When the A-wheels rotate forward and the B-wheels remain stationary, the car moves diagonally front-right. When the A-wheels rotate backward and the B-wheels remain stationary, the car moves diagonally rear-left. When the A-wheels remain stationary and the B-wheels rotate backward, the car moves diagonally rear-right.</p><img loading="lazy" height="1120" width="3584" src="'+_+'" class="common_img" style="width:500px;aspect-ratio:3584 / 1120;"><h2 id="_3-1-5-expansion-and-challenge" tabindex="-1">3.1.5 Expansion and Challenge <a class="header-anchor" href="#_3-1-5-expansion-and-challenge" aria-label="Permalink to &quot;3.1.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Mecanum-Wheel Motion Direction Deduction</strong></p><p>Given a combination of rotation directions for the four wheels, deduce the actual movement direction of the car through force analysis, and sketch a force vector diagram to verify the result.</p><p><strong>Project 2: Robot Hardware Architecture Research</strong></p><p>Research the hardware architectures of commercial warehouse AGVs and service robots, then compare the advantages and disadvantages of single-controller versus dual-controller designs.</p><h2 id="_3-1-6-q-a" tabindex="-1">3.1.6 Q&amp;A <a class="header-anchor" href="#_3-1-6-q-a" aria-label="Permalink to &quot;3.1.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: Why is the AiMecha M1 designed with a dual-controller architecture instead of a single controller?</strong></p><p><strong>Answer</strong>: The dual-controller architecture is designed for task decoupling. The chassis controller handles real-time motor control, while the controller manages programs and sensor data. Separating these tasks prevents processing interference, making the system more stable and easier to program.</p><p><strong>Q2: How do Mecanum wheels achieve omnidirectional movement, and why can standard wheels not do the same?</strong></p><p><strong>Answer</strong>: The core of the Mecanum wheel lies in its rollers angled at 45°. Ground friction can be resolved into two force components, parallel and perpendicular to the roller axis, with the perpendicular component providing the lateral thrust needed for sideways motion. With four wheels mounted symmetrically, combining different rotational directions and speeds superimposes these force components to achieve omnidirectional movement.</p><h2 id="_3-1-7-technical-support-and-product-discussion" tabindex="-1">3.1.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-1-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.1.7 Technical Support and Product Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',39))])}const S=r(b,[["render",v]]);export{C as __pageData,S as default};
